-- Partitioning system-versioned tables with PARTITION BY SYSTEM_TIME.
-- https://mariadb.com/kb/en/partitioning-and-system-versioning/

-- Default partitions (implicit).
CREATE TABLE t (x INT) WITH SYSTEM VERSIONING
  PARTITION BY SYSTEM_TIME;

-- Explicit HISTORY / CURRENT partitions.
CREATE TABLE t_explicit (x INT) WITH SYSTEM VERSIONING
  PARTITION BY SYSTEM_TIME (
    PARTITION p_hist HISTORY,
    PARTITION p_cur CURRENT
  );

-- Size-based rotation with LIMIT.
CREATE TABLE t_limit (x INT) WITH SYSTEM VERSIONING
  PARTITION BY SYSTEM_TIME LIMIT 100000 (
    PARTITION p0 HISTORY,
    PARTITION p1 HISTORY,
    PARTITION pcur CURRENT
  );

-- Time-based rotation with INTERVAL.
CREATE TABLE t_interval (x INT) WITH SYSTEM VERSIONING
  PARTITION BY SYSTEM_TIME INTERVAL 1 WEEK (
    PARTITION p0 HISTORY,
    PARTITION p1 HISTORY,
    PARTITION p2 HISTORY,
    PARTITION pcur CURRENT
  );

-- INTERVAL with STARTS, AUTO and a PARTITIONS count.
CREATE TABLE t_starts (x INT) WITH SYSTEM VERSIONING
  PARTITION BY SYSTEM_TIME INTERVAL 1 MONTH
  STARTS '2021-01-01 00:00:00' AUTO PARTITIONS 12;

-- Automatic history partition creation.
CREATE TABLE t_auto_interval (x INT) WITH SYSTEM VERSIONING
  PARTITION BY SYSTEM_TIME INTERVAL 1 HOUR AUTO;

CREATE TABLE t_auto_limit (x INT) WITH SYSTEM VERSIONING
  PARTITION BY SYSTEM_TIME LIMIT 1000 AUTO;

CREATE TABLE t_auto_explicit (x INT) WITH SYSTEM VERSIONING
  PARTITION BY SYSTEM_TIME INTERVAL 1 HOUR AUTO
  (PARTITION p0 HISTORY, PARTITION pn CURRENT);

-- Shorthand PARTITIONS count without explicit names.
CREATE TABLE t_count (x INT) WITH SYSTEM VERSIONING
  PARTITION BY SYSTEM_TIME INTERVAL 1 MONTH PARTITIONS 12;

-- Combined with subpartitioning.
CREATE TABLE t_sub (x INT) WITH SYSTEM VERSIONING
  PARTITION BY SYSTEM_TIME
    SUBPARTITION BY KEY (x)
    SUBPARTITIONS 4 (
    PARTITION ph HISTORY,
    PARTITION pc CURRENT
  );

-- Regression: MySQL-style partitioning must still parse unchanged.
CREATE TABLE t_hash (a INT) PARTITION BY HASH (a) PARTITIONS 4;
CREATE TABLE t_range (a INT) PARTITION BY RANGE (a) (
    PARTITION p0 VALUES LESS THAN (10),
    PARTITION p1 VALUES LESS THAN MAXVALUE
);
